### ✅ Fixed `/get-password` Route

Here’s the corrected and working version that:
- Takes `token` from headers.
- Verifies it.
- Extracts `username` from the token.
- Looks up the user.
- Sends back their `username` and `password`.

```js
const express = require('express');
const jwt = require('jsonwebtoken');

const JWT_SECRET = 'cuteboy'; // Use a stronger secret in production
const app = express();
app.use(express.json());

const users = [];

app.post('/signup', function (req, res) {
    const username = req.body.username;
    const password = req.body.password;

    users.push({ username, password });

    res.json({ message: 'you are signed in' });
});

app.post('/signin', function (req, res) {
    const { username, password } = req.body;

    let founduser = null;
    for (let i = 0; i < users.length; i++) {
        if (users[i].username === username && users[i].password === password) {
            founduser = users[i];
            break;
        }
    }

    if (!founduser) {
        res.json({ message: 'credentials are incorrect' });
        return;
    }

    const token = jwt.sign({ username }, JWT_SECRET);
    res.json({ token });
});

app.get('/get-password', function (req, res) {
    const token = req.headers.token;

    if (!token) {
        return res.status(401).json({ message: 'Token missing' });
    }

    try {
        const decodedData = jwt.verify(token, JWT_SECRET);
        const username = decodedData.username;

        const founduser = users.find(user => user.username === username);

        if (!founduser) {
            return res.status(404).json({ message: 'User not found' });
        }

        res.json({
            username: founduser.username,
            password: founduser.password
        });
    } catch (err) {
        res.status(401).json({ message: 'Invalid token' });
    }
});

app.listen(4000, () => {
    console.log("Server running on http://localhost:4000");
});
```

